-- Creates the refunds table: each refund of part or all of a captured payment
-- intent, made through the processor account of its successful attempt. It
-- belongs to the payments module.
--
-- A refund is inserted as EXECUTING, with its operation_id, before the
-- provider is called (Reserve), and its result is applied afterwards by a
-- conditional update that requires EXECUTING (Apply). Timestamps have no
-- database default: the application supplies them from its injected clock.
-- Identifiers are UUIDs generated by the application.

-- Targets of the composite foreign keys below: an attempt of a given intent,
-- and an intent in a given currency. Both column sets are immutable on their
-- tables, so the keys hold for the life of a refund.
ALTER TABLE payment_attempts
  ADD CONSTRAINT payment_attempts_merchant_intent_id_key UNIQUE (merchant_id, payment_intent_id, id);
ALTER TABLE payment_intents
  ADD CONSTRAINT payment_intents_merchant_id_id_currency_key UNIQUE (merchant_id, id, currency);

CREATE TABLE refunds (
  id uuid NOT NULL,
  merchant_id uuid NOT NULL,
  payment_intent_id uuid NOT NULL,
  -- The successful attempt whose capture is refunded.
  payment_attempt_id uuid NOT NULL,
  -- The account the refund goes through: the successful attempt's account,
  -- whatever its state now.
  processor_account_id uuid NOT NULL,
  -- Stable identity of the provider operation, created before the call: it is
  -- sent as the provider's idempotency key.
  operation_id uuid NOT NULL,
  -- The idempotency record that the refund request claimed. It stays in
  -- progress while the refund is EXECUTING or UNKNOWN. No foreign key: the
  -- idempotency module owns its records.
  idempotency_record_id uuid NOT NULL,
  amount_minor bigint NOT NULL,
  currency varchar(3) NOT NULL,
  status varchar(20) NOT NULL,
  provider_refund_id varchar(255),
  failure_code varchar(64),
  error_category varchar(20),
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT refunds_pkey PRIMARY KEY (id),
  CONSTRAINT refunds_merchant_id_id_key UNIQUE (merchant_id, id),
  CONSTRAINT refunds_operation_id_key UNIQUE (operation_id),
  -- The intent, its attempt, and the account of a refund always belong to its
  -- merchant; the attempt belongs to the intent, and the currency is the
  -- intent's.
  CONSTRAINT refunds_payment_intent_fkey FOREIGN KEY (merchant_id, payment_intent_id, currency)
    REFERENCES payment_intents (merchant_id, id, currency),
  CONSTRAINT refunds_payment_attempt_fkey FOREIGN KEY (merchant_id, payment_intent_id, payment_attempt_id)
    REFERENCES payment_attempts (merchant_id, payment_intent_id, id),
  CONSTRAINT refunds_processor_account_fkey FOREIGN KEY (merchant_id, processor_account_id)
    REFERENCES processor_accounts (merchant_id, id),
  -- A provider refund ID is unique only within its provider account.
  CONSTRAINT refunds_provider_refund_key UNIQUE (processor_account_id, provider_refund_id),
  CONSTRAINT refunds_amount_minor_check CHECK (amount_minor > 0),
  CONSTRAINT refunds_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT refunds_status_check CHECK (
    status IN ('EXECUTING', 'PENDING', 'SUCCEEDED', 'FAILED', 'UNKNOWN')
  ),
  CONSTRAINT refunds_provider_refund_id_check CHECK (provider_refund_id ~ '^[!-~]{1,255}$'),
  CONSTRAINT refunds_failure_code_check CHECK (failure_code ~ '^[a-z0-9_]{1,64}$'),
  -- The values mirror PROCESSOR_ERROR_CATEGORIES in packages/processor-contracts.
  CONSTRAINT refunds_error_category_check CHECK (
    error_category IN ('CONFIGURATION', 'NETWORK', 'GATEWAY', 'ISSUER_DECLINE', 'INVALID_REQUEST', 'UNKNOWN')
  ),
  -- A refund the provider accepted is always identified at the provider.
  CONSTRAINT refunds_provider_refund_required_check CHECK (
    status NOT IN ('PENDING', 'SUCCEEDED') OR provider_refund_id IS NOT NULL
  ),
  CONSTRAINT refunds_failure_code_status_check CHECK (failure_code IS NULL OR status = 'FAILED'),
  -- A failed or uncertain refund says why; the others carry no category.
  CONSTRAINT refunds_error_category_status_check CHECK (
    (status IN ('FAILED', 'UNKNOWN')) = (error_category IS NOT NULL)
  )
);

-- The refunds of one intent, oldest first, and the sums of the refund rule.
CREATE INDEX refunds_merchant_id_payment_intent_id_created_at_id_idx
  ON refunds (merchant_id, payment_intent_id, created_at, id);

COMMENT ON TABLE refunds IS 'Refunds of captured payment intents. Rows are never deleted, and a finished refund never changes.';
COMMENT ON COLUMN refunds.amount_minor IS 'Refunded amount in minor units of currency, greater than zero. Read and written as bigint, never through a floating point number.';
COMMENT ON COLUMN refunds.operation_id IS 'Provider idempotency key of the refund, created before the provider call.';
COMMENT ON COLUMN refunds.provider_refund_id IS 'Identifier of the refund at the provider, for example a Stripe re_ ID.';
COMMENT ON COLUMN refunds.failure_code IS 'The provider failure reason or error code of a FAILED refund, when the provider gives one.';
COMMENT ON COLUMN refunds.error_category IS 'Why a FAILED or UNKNOWN refund did not succeed.';

-- The last defense of the refund rule, behind the application's row lock of
-- the intent: a new refund needs an intent that is SUCCEEDED or
-- PARTIALLY_REFUNDED, and the refunds that are not FAILED (succeeded, pending,
-- executing, or unknown) must not add up to more than the intent's amount. The
-- intent row is locked FOR UPDATE first, so concurrent inserts for one intent
-- are checked one after the other, and each statement of this function reads
-- the rows committed before it ran.
CREATE FUNCTION refunds_assert_within_captured() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  intent_status varchar;
  intent_amount bigint;
  committed numeric;
BEGIN
  SELECT status, amount_minor INTO intent_status, intent_amount
    FROM payment_intents
   WHERE merchant_id = NEW.merchant_id AND id = NEW.payment_intent_id
     FOR UPDATE;
  IF intent_status NOT IN ('SUCCEEDED', 'PARTIALLY_REFUNDED') THEN
    RAISE EXCEPTION 'refunds: payment intent % is % and cannot be refunded',
      NEW.payment_intent_id, intent_status
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(amount_minor), 0) INTO committed
    FROM refunds
   WHERE merchant_id = NEW.merchant_id
     AND payment_intent_id = NEW.payment_intent_id
     AND status <> 'FAILED';
  IF committed > intent_amount THEN
    RAISE EXCEPTION 'refunds: refunds of payment intent % exceed its amount',
      NEW.payment_intent_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;

CREATE TRIGGER refunds_within_captured
AFTER INSERT ON refunds
FOR EACH ROW
EXECUTE FUNCTION refunds_assert_within_captured();

-- What a refund is never changes, a provider refund ID once learned is kept,
-- nothing returns to EXECUTING, and a finished refund (SUCCEEDED or FAILED) is
-- never updated again. PENDING and UNKNOWN may still be resolved.
CREATE FUNCTION refunds_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.merchant_id, NEW.payment_intent_id, NEW.payment_attempt_id,
      NEW.processor_account_id, NEW.operation_id, NEW.idempotency_record_id,
      NEW.amount_minor, NEW.currency, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.merchant_id, OLD.payment_intent_id, OLD.payment_attempt_id,
      OLD.processor_account_id, OLD.operation_id, OLD.idempotency_record_id,
      OLD.amount_minor, OLD.currency, OLD.created_at) THEN
    RAISE EXCEPTION 'refunds: the identity of a refund cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status IN ('SUCCEEDED', 'FAILED') THEN
    RAISE EXCEPTION 'refunds: a finished refund cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.provider_refund_id IS NOT NULL
     AND NEW.provider_refund_id IS DISTINCT FROM OLD.provider_refund_id THEN
    RAISE EXCEPTION 'refunds: a provider refund ID cannot be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.status = 'EXECUTING' AND OLD.status <> 'EXECUTING' THEN
    RAISE EXCEPTION 'refunds: a refund cannot return to EXECUTING'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER refunds_restrict_update
BEFORE UPDATE ON refunds
FOR EACH ROW
EXECUTE FUNCTION refunds_reject_invalid_update();

-- Refunds are the payment's history: deleting one would hide returned money or
-- free its amount for another refund, so deletion is rejected for every
-- statement.
CREATE FUNCTION refunds_reject_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'refunds: % is not allowed', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER refunds_restrict_delete
BEFORE DELETE OR TRUNCATE ON refunds
FOR EACH STATEMENT
EXECUTE FUNCTION refunds_reject_delete();
